// Write files and check that all en keys exist
for (const [code, data] of Object.entries(TRANSLATIONS)) {
  const filePath = path.join(__dirname, '../lib/i18n/translations', `${code}.json`);
  fs.writeFileSync(filePath, JSON.stringify(data, null, 2), 'utf8');
  console.log(`Successfully wrote ${code}.json`);
}


